<script setup lang="ts">
import { computed } from 'vue';
import type { FindingView } from '../../types/reviewPlan';
import type { PublicationPlan } from '../../types/publication';
import { reviewSituation } from '../../utils/reviewSituation';
import { reportAuthorGoal, reportLimitations, reportValidationLabel, reportSourceLink, publicationFindingTitle,
  reportChapters, unpublishedFindings, severityLabel, reviewStatusLabel, dispositionLabel, coverageLabel,
  reportReasonLabel, withheldReasonLabel } from '../../utils/reportPresentation';
import { recheckLabel } from '../../utils/prDiscussionPresentation';
import AppIcon from '../common/AppIcon.vue';
import PrDiscussionContext from '../review/PrDiscussionContext.vue';
const props = defineProps<{ plan: PublicationPlan; prUrl?: string; stale?: boolean }>();
const emit = defineEmits<{ file: [path: string]; finding: [key: string] }>();
// 正文保留原快照的冻结结论原文；stale 只切换为警告语气并标注“历史快照结论”，
// 当前版本判定由顶部 ReportContext 的 stale 情景负责，避免正文与顶部互相矛盾。
const situation = computed(() => reviewSituation(props.plan));
const digest = computed(() => props.plan.digest);
const understanding = computed(() => digest.value.change_understanding);
const observations = computed(() => (digest.value.intent_assessments || []).flatMap(intent => intent.observations.map(observation => ({ ...observation, target: intent.author_target }))));
const findings = computed(() => [...props.plan.inline_drafts, ...props.plan.summary_findings]);
const limitations = computed(() => reportLimitations(props.plan).filter(item => item !== digest.value.author_context_limitation));
const chapters = computed(() => reportChapters(props.plan));
const chapterNum = (id: string) => chapters.value.find(item => item.id === id)?.label.split(' · ')[0] || '';
const dispositions = computed(() => Object.fromEntries((digest.value.findings || [])
  .filter(item => item.disposition).map(item => [item.id, item.disposition!])));
const unpublishedGroups = computed(() => {
  const items = unpublishedFindings(props.plan);
  return [
    { key: 'confirmed', title: '机器已确认但未形成发布意见', items: items.filter(item => item.review_status === 'confirmed') },
    { key: 'pending', title: '需要人工确认的疑点（尚未确认缺陷）', items: items.filter(item => ['candidate', 'unresolved', 'unknown'].includes(item.review_status)) },
    { key: 'dismissed', title: '已排除的候选', items: items.filter(item => item.review_status === 'dismissed') },
  ].filter(group => group.items.length);
});
const investigations = computed(() => digest.value.investigations || []);
const goals = computed(() => [...digest.value.examined_goals, ...digest.value.incomplete_goals]);
const alignmentLabel = { supported: '局部证据支持', contradicted: '存在相反证据', insufficient: '证据不足', not_applicable: '不适用' };
const goalStatusLabel = (status: string) => ({ examined: '已检查', not_examined: '未检查', unsupported: '暂不支持', unknown: '未知' })[status] || status;
const investigationLabel = (answer: string) => ({ supported: '证据支持', refuted: '证据否定', unresolved: '尚未解决' })[answer] || answer;
const reliabilityLabel = (value: string) => ({ reliable: '可靠', unreliable: '存在限制', unknown: '未知' })[value] || '未知';
const locationText = (view: FindingView) => view.location
  ? `${view.location.path}:${view.location.start_line}${view.location.end_line && view.location.end_line !== view.location.start_line ? `–${view.location.end_line}` : ''}（${view.location.side === 'left' ? 'Base' : 'Head'}）`
  : '尚无可靠代码定位';
const retainedSource = (view: FindingView) => view.location ? reportSourceLink(props.prUrl || digest.value.pr_url,
  view.location.path, view.location.side === 'left' ? props.plan.snapshot.effective_base_sha : props.plan.snapshot.head_sha, view.location.start_line) : null;
const sourceLink = (path: string, side: 'head' | 'base' | null, line: number | null) => reportSourceLink(props.prUrl || digest.value.pr_url,
  path, side === 'head' ? props.plan.snapshot.head_sha : side === 'base' ? props.plan.snapshot.effective_base_sha : null, line);
</script>
<template>
  <div class="rd-doc">
    <PrDiscussionContext :review-id="plan.review_id" :stats="digest.discussion_stats" />
    <section id="rd-detail-conclusion" class="rd-detail-intro" :class="stale ? 'warning rd-intro-stale' : situation?.tone"><h3><AppIcon :name="stale ? 'history' : situation?.icon || 'help'" :size="20" />{{ situation?.title || '审查结论未知' }}<span v-if="stale" class="badge warn rd-history-badge">历史快照结论</span></h3><p>{{ situation?.description }} 覆盖情况、证据可靠性和动态验证属于不同维度。</p><p v-if="stale" class="rd-history-note">PR 已更新：以上为原 Head <code>{{ plan.snapshot.head_sha?.slice(0, 12) || '未记录' }}</code> 的冻结结论，不适用于最新提交；请重新审查后再引用。</p></section>
    <div class="rd-metric-strip"><div><strong>{{ plan.outcome.confirmed_count ?? '未知' }}</strong><small>已确认问题</small></div><div><strong>{{ plan.outcome.examined_goals ?? '?' }} / {{ plan.outcome.total_goals ?? '?' }}</strong><small>约定目标检查情况</small></div><div><strong class="rd-validation-value">{{ reportValidationLabel(plan.outcome.dynamic_validation) }}</strong><small>目标仓库动态验证</small></div></div>
    <p v-if="stale" class="rd-history-note">以上数量来自旧快照，不适用于最新 Head。</p>
    <section id="rd-detail-changes" class="rd-doc-section"><h3><span class="rd-num">{{ chapterNum('changes') }}</span>这次 PR 想解决什么？</h3><div class="rd-two-col"><div class="rd-info-panel"><h4>PR 目标</h4><p>{{ reportAuthorGoal(plan) }}</p></div><div class="rd-info-panel"><h4>代码变化 · 局部静态观察</h4><p v-if="understanding?.actual_changes">{{ understanding.actual_changes }}</p><ul v-else-if="digest.actual_changes?.length"><li v-for="(change, index) in digest.actual_changes" :key="index">{{ change }}</li></ul><p v-else>尚无归纳后的代码变化记录。</p></div></div><div v-if="understanding?.alignment" class="rd-notice warn rd-space"><AppIcon name="info" :size="17" /><div>{{ understanding.alignment }}</div></div></section>
    <section id="rd-detail-evidence" class="rd-doc-section"><h3><span class="rd-num">{{ chapterNum('evidence') }}</span>核对到的代码依据</h3><p>下列观察和问题均来自本轮计划。文件位置与证据引用保留服务端提供的对应关系。</p>
      <article v-for="(observation, index) in observations" :key="`${observation.goal_id}:${index}`" class="rd-evidence"><header><strong>{{ observation.target }}</strong><span class="badge" :class="observation.alignment === 'supported' ? 'success' : 'warning'">{{ alignmentLabel[observation.alignment] || observation.alignment }}</span></header><button type="button" class="rd-path" @click="emit('file', observation.path)">{{ observation.path }}{{ observation.start_line ? ` · L${observation.start_line}` : '' }} · {{ observation.side === 'base' ? 'Base' : 'Head' }}<AppIcon name="arrow-right" :size="13" /></button><a v-if="sourceLink(observation.path, observation.side, observation.start_line)" class="rd-source-link" :href="sourceLink(observation.path, observation.side, observation.start_line)!" target="_blank" rel="noreferrer">查看快照源码 ↗</a><p>{{ observation.actual_behavior }}</p><div v-if="observation.evidence_ids.length" class="rd-evidence-ids"><code v-for="id in observation.evidence_ids" :key="id">{{ id }}</code></div><ul v-if="observation.limitations.length"><li v-for="(item, i) in observation.limitations" :key="i">{{ item }}</li></ul></article>
      <article v-for="finding in findings" :key="finding.finding_key" class="rd-evidence"><header><button type="button" class="rd-text-button" @click="emit('finding', finding.finding_key)">{{ publicationFindingTitle(finding) }}</button><span class="badge" :class="['critical', 'high'].includes(finding.severity) ? 'danger' : 'warning'">{{ severityLabel(finding.severity) }}</span></header><button type="button" class="rd-path" @click="emit('file', finding.anchor.file_path)">{{ finding.anchor.file_path || '未提供文件' }}{{ finding.anchor.start_line ? ` · L${finding.anchor.start_line}${finding.anchor.end_line && finding.anchor.end_line !== finding.anchor.start_line ? `–${finding.anchor.end_line}` : ''}` : '' }} · {{ finding.anchor.side === 'base' ? 'Base' : finding.anchor.side === 'head' ? 'Head' : '侧别未知' }}<AppIcon name="arrow-right" :size="13" /></button><a v-if="sourceLink(finding.anchor.file_path, finding.anchor.side, finding.anchor.start_line)" class="rd-source-link" :href="sourceLink(finding.anchor.file_path, finding.anchor.side, finding.anchor.start_line)!" target="_blank" rel="noreferrer">查看快照源码 ↗</a><p>{{ finding.evidence_summary || finding.affected_behavior }}</p><p v-if="finding.failure_scenario"><strong>触发场景：</strong>{{ finding.failure_scenario }}</p><p v-if="finding.recommendation"><strong>建议：</strong>{{ finding.recommendation }}</p><div v-if="finding.evidence_ids.length" class="rd-evidence-ids"><code v-for="id in finding.evidence_ids" :key="id">{{ id }}</code></div><p v-if="dispositions[finding.finding_key]" class="rd-empty-note">人工处理：{{ dispositionLabel(dispositions[finding.finding_key]!.status) }}<template v-if="dispositions[finding.finding_key]!.reason">；原因：{{ dispositions[finding.finding_key]!.reason }}</template></p></article>
      <p v-if="!observations.length && !findings.length" class="rd-empty-note">本轮没有可展示的逐项代码观察或已确认问题。可在技术审计导出中查看目标记录；这不表示所有业务路径均已核验。</p>
    </section>
    <section v-if="unpublishedGroups.length" id="rd-detail-retained" class="rd-doc-section"><h3><span class="rd-num">{{ chapterNum('retained') }}</span>未进入发布正文的记录</h3><p>以下记录未通过发布准入或尚未确认，不能作为 PR 评论发布；保留用于核对证据、人工判断与后续处理。</p>
      <template v-for="group in unpublishedGroups" :key="group.key"><h4 class="rd-subhead">{{ group.title }}（{{ group.items.length }} 项）</h4>
        <article v-for="view in group.items" :key="view.id" class="rd-evidence"><header><strong>{{ view.title || '未命名记录' }}</strong><span class="rd-evidence-flags"><span class="badge" :class="view.review_status === 'dismissed' ? 'neutral' : 'warning'">{{ reviewStatusLabel(view.review_status) }}</span><span class="badge neutral">{{ severityLabel(view.severity) }}</span></span></header><button v-if="view.location" type="button" class="rd-path" @click="emit('file', view.location.path)">{{ locationText(view) }}<AppIcon name="arrow-right" :size="13" /></button><span v-else class="rd-empty-note">{{ locationText(view) }}</span><a v-if="retainedSource(view)" class="rd-source-link" :href="retainedSource(view)!" target="_blank" rel="noreferrer">查看快照源码 ↗</a><p v-if="view.impact"><strong>影响：</strong>{{ view.impact }}</p><p v-if="view.message"><strong>触发场景：</strong>{{ view.message }}</p><p v-if="view.recommendation"><strong>建议：</strong>{{ view.recommendation }}</p><p v-if="view.disposition" class="rd-empty-note">人工处理：{{ dispositionLabel(view.disposition.status) }}<template v-if="view.disposition.reason">；原因：{{ view.disposition.reason }}</template></p><ul v-if="view.limitations.length"><li v-for="(item, i) in view.limitations" :key="i">{{ item }}</li></ul><p v-if="view.review_status !== 'confirmed'" class="rd-empty-note">以上为候选或排除记录，不能作为已核验的发布评论。</p></article>
      </template>
    </section>
    <section id="rd-detail-gaps" class="rd-doc-section"><h3><span class="rd-num">{{ chapterNum('gaps') }}</span>尚未核验的部分</h3><ul v-if="limitations.length" class="rd-check-list"><li v-for="(item, index) in limitations" :key="index"><AppIcon name="alert" :size="15" /><span>{{ item }}</span></li></ul><p v-else>本轮未提供额外局限记录；静态检查不能证明全部业务路径正确。</p><h4>来源与验证边界</h4><p v-if="reportAuthorGoal(plan) !== '未记录明确的作者目标。'">PR 目标来自作者提供的 PR 描述或标题，以本轮保存的内容为准；仅作审查背景，不代表目标已实现。</p><p v-if="digest.author_context_limitation">{{ digest.author_context_limitation }}</p><div class="rd-notice"><AppIcon name="flask" :size="17" /><div>动态验证：{{ reportValidationLabel(plan.outcome.dynamic_validation) }}。<template v-if="plan.outcome.dynamic_validation === 'not_executed'">未执行目标仓库代码、测试或构建。读取测试源码不等于测试通过。</template><template v-else>请结合以下来源、阶段与快照记录判断，不能将独立补丁结果视为当前 Head 通过。</template></div></div><ul v-if="digest.validations?.length"><li v-for="item in digest.validations" :key="item.id">{{ item.source }} / {{ item.stage }}：{{ item.status }}。{{ item.reason }}</li></ul></section>
    <section id="rd-detail-actions" class="rd-doc-section"><h3><span class="rd-num">{{ chapterNum('actions') }}</span>建议下一步<span v-if="stale" class="badge warn rd-history-badge">历史快照结论</span></h3><p>{{ digest.merge_decision?.advice || '核对未决证据、业务预期与项目 CI，在提交变化后重新审查受影响内容。' }}</p><p v-if="stale" class="rd-empty-note">以上建议基于旧快照；PR 有新提交时需重新审查，不能直接用于最新版本。</p><p v-if="digest.termination_reason" class="rd-empty-note">终止原因：{{ digest.termination_reason }}</p></section>
    <section id="rd-detail-appendix" class="rd-doc-section"><h3><span class="rd-num">附</span>审查范围与记录</h3><p>已检查 {{ plan.outcome.examined_goals ?? '?' }} / {{ plan.outcome.total_goals ?? '?' }} 项约定目标；审查完整性 {{ coverageLabel(plan.outcome.review_completeness) }}；运行可靠性 {{ reliabilityLabel(plan.outcome.runtime_reliability) }}。原始身份与逐项记录按需展开。</p>
      <details class="rd-accordion"><summary>审查身份与快照</summary><dl class="rd-snapshot"><dt>审查记录</dt><dd><code>{{ plan.review_id }}</code></dd><dt>Head SHA</dt><dd><code>{{ plan.snapshot.head_sha || '未记录' }}</code></dd><dt>Effective Base</dt><dd><code>{{ plan.snapshot.effective_base_sha || '未记录' }}</code></dd><dt>审查完整性</dt><dd>{{ coverageLabel(plan.outcome.review_completeness) }} · 运行可靠性 {{ reliabilityLabel(plan.outcome.runtime_reliability) }}</dd></dl></details>
      <details v-if="goals.length" class="rd-accordion"><summary>目标记录（{{ goals.length }} 项）</summary><div class="rd-accordion-content rd-table-wrap"><table><thead><tr><th>文件 / 目标</th><th>来源</th><th>状态与记录含义</th></tr></thead><tbody><tr v-for="(goal, index) in goals" :key="`${goal.goal_id}:${index}`"><td><button v-if="goal.path" type="button" class="rd-path" @click="emit('file', goal.path)">{{ goal.path }}{{ goal.start_line ? `:${goal.start_line}${goal.end_line && goal.end_line !== goal.start_line ? `–${goal.end_line}` : ''}` : '' }}</button><span v-else>{{ goal.goal_id || '未提供路径' }}</span></td><td>{{ goal.side === 'base' ? 'Base 静态记录' : goal.side === 'head' ? 'Head 静态记录' : '未记录侧别' }}</td><td>{{ goalStatusLabel(goal.status) }}<small v-if="goal.reason">{{ goal.reason }}</small></td></tr></tbody></table><p v-if="!goals.length">没有可用的逐项目标记录。</p></div></details>
      <details v-if="digest.actual_changes?.length" class="rd-accordion"><summary>变更文件（{{ digest.actual_changes.length }} 项）</summary><div class="rd-accordion-content"><ul><li v-for="(change, index) in digest.actual_changes" :key="index">{{ change }}</li></ul></div></details>
      <details v-if="digest.excluded_files.length" class="rd-accordion"><summary>未纳入审查的文件（{{ digest.excluded_files.length }} 项）</summary><div class="rd-accordion-content"><ul><li v-for="item in digest.excluded_files" :key="`${item.path}:${item.reason}`">{{ item.path }}：{{ item.reason }}</li></ul></div></details>
      <details v-if="investigations.length" class="rd-accordion"><summary>调查记录（{{ investigations.length }} 项）</summary><div class="rd-accordion-content"><article v-for="(item, index) in investigations" :key="index" class="rd-evidence"><strong>{{ item.proposition }}</strong><p>{{ investigationLabel(item.answer) }}：{{ item.reason || '未提供说明' }}</p><ul v-if="item.limitations.length"><li v-for="(limit, i) in item.limitations" :key="i">{{ limit }}</li></ul></article></div></details>
      <details v-if="plan.outcome.reason_codes.length" class="rd-accordion"><summary>原因代码（{{ plan.outcome.reason_codes.length }} 项）</summary><div class="rd-accordion-content"><ul><li v-for="reason in plan.outcome.reason_codes" :key="reason">{{ reportReasonLabel(reason) }}（<code>{{ reason }}</code>）</li></ul></div></details>
      <details v-if="plan.withheld_findings.length" class="rd-accordion"><summary>发布准入扣留记录（{{ plan.withheld_findings.length }} 项）</summary><div class="rd-accordion-content"><ul><li v-for="item in plan.withheld_findings" :key="`${item.candidate_id}:${item.reason_code}`"><code>{{ item.candidate_id }}</code>：{{ withheldReasonLabel(item.reason_code) }}（<code>{{ item.reason_code }}</code>）</li></ul></div></details>
      <details v-if="digest.discussion_rechecks?.length" class="rd-accordion"><summary>历史讨论复核（{{ digest.discussion_rechecks.length }} 项）</summary><div class="rd-accordion-content"><ul><li v-for="item in digest.discussion_rechecks" :key="item.discussion_id"><code>{{ item.discussion_id }}</code>：{{ recheckLabel(item.status) }}。{{ item.reason }}<template v-if="item.evidence_ids.length"><span class="rd-evidence-ids"><code v-for="id in item.evidence_ids" :key="id">{{ id }}</code></span></template><ul v-if="item.limitations.length"><li v-for="(limit, i) in item.limitations" :key="i">{{ limit }}</li></ul></li></ul></div></details>
    </section>
  </div>
</template>
